# Recipe card renderer source

Write the first block verbatim to `/workspace/recipe-kit/render_recipe.py` and the second to `/workspace/recipe-kit/example-banana-bread.json` (copy exactly; do not retype or "fix" anything), then follow the first-run steps in the recipe-card skill.

## render_recipe.py

```python
#!/usr/bin/env python3
"""
render_recipe.py - render a recipe as a "Cooking for Engineers" tabular recipe card
(Michael Chu style) to HTML and PNG.

Usage:
    python3 render_recipe.py recipe.json [-o OUT_BASENAME] [--wide] [--max-cols 4]
                             [--width 620] [--no-png]
    -> writes OUT_BASENAME.html and OUT_BASENAME.png (default: next to the JSON)

Modes:
  phone (default): the recipe is split into ordered stages, each its own narrow table
      (~430 CSS px wide, 17px+ text), stacked with a heading per stage, followed by a
      numbered "Cook from this" list. PNG is a tall full-page screenshot at device scale
      factor 2; the HTML is self-contained with a mobile viewport meta tag.
  --wide: the original single wide grid (good for printing). If the JSON has stages they
      are stitched back into one tree (each stage reference is replaced by that stage's tree).

JSON input. Leaves = ingredients, internal nodes = steps with children.

Single tree (phone mode cuts it into tables that fit the column and width budgets):
{
  "title": "Banana Nut Bread", "yield": "about 10 servings",
  "prep": ["Butter and flour a loaf pan", "Preheat oven to 350°F (170°C)"],
  "notes": ["optional lines printed under the card"], "source": "URL / credit",
  "root": {"step": "cool on wire rack", "children": [
    {"step": "bake 350°F (170°C) 55 min.", "label": "baked loaf", "children": [
      {"step": "fold", "children": [
        {"step": "mash", "children": [{"us": "2 large", "metric": "250 g", "item": "ripe bananas"}]},
        {"text": "6 Tbs. (90 mL) butter"}
      ]}
    ]}
  ]}
}

Explicit stages (used instead of "root"):
  "stages": [
    {"id": "brown", "name": "Prep and brown", "prep": ["optional full-width rows"],
     "root": {"step": "brown 4 min. per side", "children": [...]}},
    {"id": "port", "name": "Port reduction", "side": true, "root": {...}},
    {"name": "Braise", "root": {"step": "braise", "children": [
        {"ref": "browned ribs", "stage": "brown"},      # -> bold "browned ribs (stage 1)"
        ...]}}
  ]

Node fields:
  ingredient leaf : {"text": "..."} or {"us": "...", "metric": "...", "item": "..."}
                    (rendered "us (metric) item"; metric optional)
  stage reference : {"ref": "browned ribs", "stage": <stage id or 1-based number>}
                    (--wide inlines the referenced stage's tree at its first reference; add
                     "wide_inline": false to a ref to keep it a bold leaf there instead)
  step            : {"step": "text", "children": [...],
                     "label": optional name of its result (used when auto-split makes it a ref),
                     "say": optional full sentence for the "Cook from this" list,
                     "col": optional forced column (1 = first step column)}
  "root" (top level or per stage) may be one node or a list of independent trees.
Phone mode keeps text at 17px, limits each table to the step columns that fit
140px of ingredient space and 120px per step at 430px. Single trees become named
stages numbered 1, 2, etc. Explicit stages keep their names and number split parts
as 1, 1.2, etc. On narrower viewports, tables scroll horizontally.
Optional top-level styling (wide mode): "width" (table px, default 620),
"ingredient_width" (px, default 155), "step_min_width" (px, default 0).

Layout rules (each table):
  * each leaf is one row (left column);
  * a step's column = its height above the leaves (1 + max child height), so the final
    chain of single-child steps becomes successive right-most columns spanning all rows;
  * a step's rowspan = number of leaves beneath it;
  * gaps between a child and its parent's column get empty cells; empty filler cells of
    adjacent siblings in the same column are merged (as in the reference card).
"""
import argparse, copy, html, json, math, os, sys

GREEN = "#4f9549"
BASE_CSS = """
body { background:#fefdcb; margin:0; color:#000;
       font-family:'DejaVu Sans','Bitstream Vera Sans',Verdana,Arial,sans-serif; }
.title b { font-weight:bold; }
table.cfe { border-collapse:collapse; border:3px solid %(g)s; background:#fff; }
table.cfe td { border:2px solid %(g)s; background:#fff; vertical-align:middle; line-height:1.3; }
table.cfe td.prep, table.cfe td.step { text-align:center; }
table.cfe td.ing { text-align:left; }
table.cfe td.ing b { font-weight:bold; }
""" % {"g": GREEN}

WIDE_CSS = """
body { padding:14px 14px 18px 14px; font-size:17px; }
.card { display:inline-block; }
.title { font-size:19px; margin:0 0 2px 0; white-space:nowrap; }
table.cfe { width:%(width)dpx; }
table.cfe td { padding:4px 6px; }
table.cfe td.step, table.cfe td.empty { min-width:%(stepw)dpx; }
table.cfe td.ing { width:%(ingw)dpx; }
.notes { width:%(width)dpx; font-size:13px; margin-top:8px; line-height:1.35; }
"""

PHONE_W = 430          # CSS px width of each stage table
PHONE_PAD = 8
PHONE_MIN_FONT = 17
# At 17px, 140px keeps ingredient amounts readable; 120px fits short steps.
PHONE_MIN_ING = 140
PHONE_MIN_STEP = 120
PHONE_CSS = """
html { -webkit-text-size-adjust:100%%; }
body { padding:%(pad)dpx; font-size:%(font)dpx; }
.card { width:%(w)dpx; max-width:100%%; overflow-x:auto; }
.title { font-size:21px; line-height:1.3; margin:4px 0 10px 0; }
h2.stage { font-size:19px; margin:18px 0 6px 0; color:#2e6b2a; line-height:1.25; }
h2.stage .num { display:inline-block; background:%(g)s; color:#fff; border-radius:4px;
                padding:0 7px; margin-right:6px; }
h2.stage .side { font-weight:normal; font-size:16px; color:#555; }
table.cfe { width:100%%; table-layout:auto; }
table.cfe td { padding:5px 3px; font-size:%(font)dpx; overflow-wrap:break-word; hyphens:auto; }
table.cfe td.ing { padding:5px 6px; }
table.cfe.fixed { table-layout:fixed; }
.cook { margin-top:22px; }
.cook h2 { font-size:20px; margin:0 0 4px 0; color:#2e6b2a; }
.cook h3 { font-size:17px; margin:12px 0 2px 0; }
.cook ol { margin:0; padding-left:30px; font-size:17px; line-height:1.4; }
.cook li { margin:3px 0; }
.notes { font-size:14px; margin-top:16px; line-height:1.4; color:#333; overflow-wrap:anywhere; }
""" % {"pad": PHONE_PAD, "w": PHONE_W, "g": GREEN, "font": PHONE_MIN_FONT}


# ---------------------------------------------------------------- tree helpers
def is_leaf(n):
    return "step" not in n

def is_ref(n):
    return "ref" in n

def ing_text(n):
    if "text" in n:
        return n["text"]
    s = n.get("us", "").strip()
    if n.get("metric"):
        s += (" " if s else "") + "(" + n["metric"] + ")"
    if n.get("item"):
        s += (" " if s else "") + n["item"]
    return s

try:                                   # optional: soft hyphens so narrow phone columns can break long words
    import pyphen
    _HYPH = pyphen.Pyphen(lang="en_US")
except Exception:
    _HYPH = None
SOFT_HYPHENS = False                   # switched on in phone mode

def _hy_word(m):
    w = m.group(0)
    pos = [p for p in _HYPH.positions(w) if 3 <= p <= len(w) - 3]
    for p in reversed(pos):
        w = w[:p] + "\u00ad" + w[p:]
    return w

def esc(s):
    if SOFT_HYPHENS and _HYPH is not None:
        import re
        s = re.sub(r"[A-Za-z]{7,}", _hy_word, s)
    return html.escape(s).replace("\n", "<br>")

def leaf_html(n):
    if is_ref(n) and n.get("_from"):          # wide mode: an un-inlined stage reference
        return "<b>%s (from: %s)</b>" % (esc(n["ref"]), esc(n["_from"]))
    if is_ref(n):
        return "<b>%s (stage %s)</b>" % (esc(n["ref"]), n.get("_num", n.get("stage", "?")))
    return esc(ing_text(n))

def leaf_plain(n):
    if is_ref(n):
        return "%s (stage %s)" % (n["ref"], n.get("_num", n.get("stage", "?")))
    return ing_text(n)

def as_list(r):
    return r if isinstance(r, list) else [r]

def height(n):
    if is_leaf(n):
        n["_h"] = 0
        return 0
    if not n.get("children"):
        raise ValueError("step %r has no children" % n["step"])
    hs = [height(c) for c in n["children"]]
    n["_h"] = max(n.get("col", 0), 1 + max(hs))
    if n["_h"] <= max(hs):
        raise ValueError("forced col for %r is not right of its children" % n["step"])
    return n["_h"]


# ---------------------------------------------------------------- grid layout
def layout(roots):
    """Return (leaves, cells, ncols). cells: list of dict(row, col, rowspan, text, kind)."""
    leaves, cells = [], []

    def fill(k, run):
        cells.append(dict(row=run[0], col=k, rowspan=run[1], text="", kind="empty"))

    def place(n):
        start = len(leaves)
        if is_leaf(n):
            leaves.append(n)
        else:
            for c in n["children"]:
                place(c)
        n["_r0"], n["_rn"] = start, len(leaves) - start
        if not is_leaf(n):
            cells.append(dict(row=start, col=n["_h"], rowspan=n["_rn"], text=n["step"], kind="step"))
            for k in range(1, n["_h"]):
                run = None
                for c in n["children"]:
                    if c["_h"] < k:
                        run = [c["_r0"], c["_rn"]] if run is None else [run[0], run[1] + c["_rn"]]
                    else:
                        if run:
                            fill(k, run)
                        run = None
                if run:
                    fill(k, run)

    for r in roots:
        height(r)
    ncols = max(r["_h"] for r in roots)
    for r in roots:
        place(r)
        for k in range(r["_h"] + 1, ncols + 1):
            fill(k, [r["_r0"], r["_rn"]])
    grid = {}
    for c in cells:
        for rr in range(c["row"], c["row"] + c["rowspan"]):
            key = (rr, c["col"])
            if key in grid:
                raise AssertionError("cell overlap at %r" % (key,))
            grid[key] = c
    for rr in range(len(leaves)):
        for k in range(1, ncols + 1):
            if (rr, k) not in grid:
                raise AssertionError("uncovered cell at %r" % ((rr, k),))
    return leaves, cells, ncols

CHAR_PX = 10.5     # rough width of one character at 17px DejaVu Sans (a little generous)
CELL_PAD_PX = 10   # horizontal padding + border of a phone step cell

def _min_chunk_px(text):
    """Estimated px of the widest piece of text that cannot be broken (after soft hyphens)."""
    import re
    best = 0
    words = [x for w in text.split() for x in re.findall(r"[^-]+-?|-", w)]   # browsers break after "-"
    for w in words:
        pieces = [w]
        if _HYPH is not None and len(w) >= 7 and w.rstrip(",;.:)").isalpha():
            pos = [p for p in _HYPH.positions(w) if 3 <= p <= len(w) - 3]
            cuts = [0] + pos + [len(w)]
            pieces = [w[a:b] + ("-" if b < len(w) else "") for a, b in zip(cuts, cuts[1:])]
        best = max(best, max(len(x) for x in pieces))
    return best * CHAR_PX + CELL_PAD_PX

def phone_col_widths(leaves, cells, ncols, ing_pct, total=PHONE_W - 6):
    """Return column percentages sized for text, with ingredient and step width floors."""
    if not ncols:
        return [100.0]
    need = [0.0] * (ncols + 1)
    for leaf in leaves:                 # ingredient column: bold refs are ~10% wider
        need[0] = max(need[0], _min_chunk_px(leaf_plain(leaf)) * (1.1 if is_ref(leaf) else 1.0))
    for c in cells:
        if c["kind"] == "step":
            need[c["col"]] = max(need[c["col"]], _min_chunk_px(c["text"]))
    ing = total * ing_pct / 100.0
    share = (total - ing) / ncols
    w = [max(share, need[k]) for k in range(1, ncols + 1)]
    extra = sum(w) - (total - ing)
    if extra > 0:                       # take from the ingredient column first
        give = min(extra, ing - max(total * 0.22, need[0]))
        ing -= max(give, 0)
        extra -= max(give, 0)
    if extra > 0:                       # then from step columns that have slack
        slack = [max(w[i] - need[i + 1], 0) for i in range(ncols)]
        tot = sum(slack)
        if tot > 0:
            w = [w[i] - extra * slack[i] / tot if extra < tot else need[i + 1] for i in range(ncols)]
    else:                               # spare room returns to the ingredient column
        ing += -extra
    allw = [ing] + w
    s = sum(allw)
    widths = [100.0 * x / s for x in allw]
    floors = [PHONE_MIN_ING] + [PHONE_MIN_STEP] * ncols
    current = [total * round(pct, 2) / 100.0 for pct in widths]
    if all(w >= floor for w, floor in zip(current, floors)):
        return widths
    percentage_rounding_px = total / 10000
    safe_floors = [floor + percentage_rounding_px for floor in floors]
    spare = total - sum(safe_floors)
    surplus = [max(w - floor, 0.0) for w, floor in zip(current, safe_floors)]
    weight = sum(surplus)
    projected = [floor + spare * (value / weight if weight else 1.0 / len(safe_floors))
                 for floor, value in zip(safe_floors, surplus)]
    return [100.0 * w / total for w in projected]

def table_html(roots, prep=(), ing_pct=None):
    leaves, cells, ncols = layout(roots)
    ing_style = ""
    colgroup = ""
    if ing_pct:   # phone mode: fixed layout, ingredient column narrower as step columns grow,
                  # remaining width shared equally by the step columns
        pct = {1: 44, 2: 40, 3: 34}.get(ncols, 26)
        widths = phone_col_widths(leaves, cells, ncols, pct)
        colgroup = "<colgroup>%s</colgroup>" % "".join("<col style='width:%.2f%%'>" % w for w in widths)
        floors = [PHONE_MIN_ING] + [PHONE_MIN_STEP] * ncols
        min_width = max(math.ceil(floor * 100 / round(width, 2))
                        for floor, width in zip(floors, widths)) + 6
    by_row = {}
    for c in cells:
        by_row.setdefault(c["row"], []).append(c)
    out = ["<table class='cfe%s'%s>%s" % (
        " fixed" if ing_pct else "", " style='min-width:%dpx'" % min_width if ing_pct else "", colgroup)]
    for p in prep:
        out.append("<tr><td class='prep' colspan='%d'>%s</td></tr>" % (ncols + 1, esc(p)))
    for r, leaf in enumerate(leaves):
        row = ["<td class='ing'%s>%s</td>" % (ing_style, leaf_html(leaf))]
        for c in sorted(by_row.get(r, []), key=lambda c: c["col"]):
            rs = " rowspan='%d'" % c["rowspan"] if c["rowspan"] > 1 else ""
            row.append("<td class='%s'%s>%s</td>" % (c["kind"], rs, esc(c["text"])))
        out.append("<tr>" + "".join(row) + "</tr>")
    out.append("</table>")
    return "\n".join(out), ncols


# ---------------------------------------------------------------- stages
def get_stages(recipe, max_cols):
    """Return list of stages: dict(name, roots, prep, side). Resolves refs to stage numbers."""
    if recipe.get("stages"):
        stages = []
        for i, s in enumerate(recipe["stages"]):
            stages.append(dict(name=s.get("name", "Stage %d" % (i + 1)), id=s.get("id"),
                               roots=copy.deepcopy(as_list(s["root"])), prep=s.get("prep", []),
                               side=s.get("side", False)))
        ids = {s["id"]: i + 1 for i, s in enumerate(stages) if s["id"] is not None}

        def resolve(n, here):
            if is_ref(n):
                st = n.get("stage")
                num = ids.get(st) if not isinstance(st, int) else st
                if num is None or not (1 <= num < here):
                    raise ValueError("ref %r points to unknown or later stage %r" % (n["ref"], st))
                n["_num"] = num
            for c in n.get("children", []):
                resolve(c, here)
        for i, s in enumerate(stages):
            for r in s["roots"]:
                resolve(r, i + 1)
        return stages
    return auto_split(copy.deepcopy(as_list(recipe["root"])), max_cols)

def cap(s):
    return s[:1].upper() + s[1:]

def short(s, words=5):
    w = s.replace(";", "").replace(",", "").split()
    return " ".join(w[:words]) + ("…" if len(w) > words else "")

def auto_split(roots, max_cols):
    """Cut sub-trees so that no stage has more than max_cols step columns."""
    cut = []   # list of (node) in post-order; each becomes a stage

    def proc(n):
        if is_leaf(n):
            return 0
        hs = [proc(c) for c in n["children"]]
        if 1 + max(hs) > max_cols:
            for i, c in enumerate(n["children"]):
                if hs[i] >= max_cols:
                    stage = {"node": c}
                    cut.append(stage)
                    n["children"][i] = {"ref": c.get("label") or "result of “%s”" % short(c["step"]),
                                        "_stage": stage}
                    hs[i] = 0
        return 1 + max(hs)

    for r in roots:
        proc(r)
    stages = []
    for st in cut:
        n = st["node"]
        stages.append(dict(name=cap(n.get("label") or short(n["step"], 6)),
                           roots=[n], prep=[], side=False))
        st["num"] = len(stages)
    last = roots[-1] if roots and not is_leaf(roots[-1]) else None
    stages.append(dict(name=(cap(last.get("label") or short(last["step"], 6)) if last else "Finish"),
                       roots=roots, prep=[], side=False))

    def num(n):
        if is_ref(n) and "_stage" in n:
            n["_num"] = n["_stage"]["num"]
        for c in n.get("children", []):
            num(c)
    for s in stages:
        for r in s["roots"]:
            num(r)
    return stages

def stitch(recipe):
    """Explicit stages -> one list of roots for the wide grid (inline first use of each stage)."""
    stages = get_stages(recipe, 10 ** 6)
    used = set()

    def sub(n):
        if is_ref(n):
            k = n["_num"]
            src = stages[k - 1]["roots"]
            if k not in used and len(src) == 1 and n.get("wide_inline", True):
                used.add(k)
                return sub(src[0])
            n["_from"] = stages[k - 1]["name"]
            return n
        if not is_leaf(n):
            n["children"] = [sub(c) for c in n["children"]]
        return n

    roots = [sub(r) for r in stages[-1]["roots"]]
    # stages nobody consumed (other than the last) are kept as extra trees, in order
    extra = [sub(stages[i]["roots"][j]) for i in range(len(stages) - 1) if (i + 1) not in used
             for j in range(len(stages[i]["roots"]))]
    for s in stages:   # stage-level prep rows go to the top
        recipe.setdefault("_prep_extra", []).extend(s["prep"])
    return extra + roots


# ---------------------------------------------------------------- cook list
def cook_steps(n, out):
    if is_leaf(n):
        return
    for c in n["children"]:
        cook_steps(c, out)
    if n.get("say"):
        out.append(n["say"])
        return
    t = cap(n["step"])
    leaves = [leaf_plain(c) for c in n["children"] if is_leaf(c)]
    if leaves:
        t += (": " if len(leaves) == len(n["children"]) else ", adding: ") + "; ".join(leaves)
    out.append(t)


# ---------------------------------------------------------------- page builders
def title_html(recipe):
    t = "<b>%s</b>" % esc(recipe["title"])
    if recipe.get("yield"):
        t += " (%s)" % esc(recipe["yield"])
    return "<div class='title'>%s</div>" % t

def notes_html(recipe):
    extra = list(recipe.get("notes", []))
    if recipe.get("source"):
        extra.append("Source: " + recipe["source"])
    return "<div class='notes'>%s</div>" % "<br>".join(esc(x) for x in extra) if extra else ""

def render_wide(recipe, width=620):
    recipe = copy.deepcopy(recipe)
    roots = stitch(recipe) if recipe.get("stages") else as_list(recipe["root"])
    css = BASE_CSS + WIDE_CSS % dict(width=recipe.get("width", width),
                                      ingw=recipe.get("ingredient_width", 155),
                                      stepw=recipe.get("step_min_width", 0))
    tbl, _ = table_html(roots, list(recipe.get("prep", [])) + recipe.get("_prep_extra", []))
    return ("<!DOCTYPE html><html lang='en'><head><meta charset='utf-8'><title>%s</title>"
            "<style>%s</style></head><body><div class='card'>%s%s%s</div></body></html>"
            % (esc(recipe["title"]), css, title_html(recipe), tbl, notes_html(recipe)))

def phone_stages(recipe, max_cols):
    """Return logical stages and width-budgeted presentation parts.

    Single trees use each auto-split piece as a named logical stage.
    Explicit stages retain their names across numbered continuation parts.
    Forced columns are checked on the original trees and kept when they fit.
    Oversized trees are split from copies without forced column hints.
    References to explicit stages point to their final parts.
    """
    if max_cols <= 0:
        raise ValueError("--max-cols must be a positive number of step columns")
    budget = (PHONE_W - 6 - PHONE_MIN_ING) // PHONE_MIN_STEP
    limit = min(max_cols, budget)
    logical = get_stages(recipe, 10 ** 6)
    parts = []
    final_label = {}

    def visit(n, fn):
        fn(n)
        for child in n.get("children", []):
            visit(child, fn)

    for i, stage in enumerate(logical, 1):
        original_cols = layout(stage["roots"])[2]
        roots = copy.deepcopy(stage["roots"])
        if original_cols > limit:
            for root in roots:
                visit(root, lambda n: n.pop("col", None))
        split = auto_split(roots, limit)
        if not recipe.get("stages"):
            return split, [dict(part, num=str(j)) for j, part in enumerate(split, 1)]
        labels = [str(i) if j == 1 else "%d.%d" % (i, j)
                  for j in range(1, len(split) + 1)]
        final_label[i] = labels[-1]
        for j, part in enumerate(split):
            def number_ref(n):
                if is_ref(n) and "_stage" in n:
                    n["_num"] = labels[n["_num"] - 1]
                elif is_ref(n) and "_num" in n:
                    n["_num"] = final_label[n["_num"]]
            for root in part["roots"]:
                visit(root, number_ref)
            parts.append(dict(num=labels[j], name=stage["name"] + (" (cont.)" if j else ""),
                              roots=part["roots"], prep=stage["prep"] if not j else [],
                              side=stage["side"]))

    for stage in logical:
        def number_original_ref(n):
            if is_ref(n) and "_num" in n:
                n["_num"] = final_label[n["_num"]]
        for root in stage["roots"]:
            visit(root, number_original_ref)
    return logical, parts

def render_phone(recipe, max_cols=4):
    global SOFT_HYPHENS
    logical, stages = phone_stages(recipe, max_cols)
    SOFT_HYPHENS = True
    body = [title_html(recipe)]
    if recipe.get("prep"):
        body.append("<h2 class='stage'>Before you start</h2>")
        body.append("<table class='cfe'>%s</table>" % "".join(
            "<tr><td class='prep'>%s</td></tr>" % esc(p) for p in recipe["prep"]))
    for s in stages:
        side = " <span class='side'>(side stage)</span>" if s["side"] else ""
        body.append("<h2 class='stage'><span class='num'>%s</span>%s%s</h2>" % (s["num"], esc(s["name"]), side))
        tbl, _ = table_html(s["roots"], s["prep"], ing_pct=True)
        body.append(tbl)
    # numbered cook list (full-width text: no soft hyphens needed)
    SOFT_HYPHENS = False
    body.append("<div class='cook'><h2>Cook from this</h2>")
    n = 1
    if recipe.get("prep"):
        body.append("<h3>Before you start</h3><ol start='%d'>%s</ol>" % (
            n, "".join("<li>%s</li>" % esc(p) for p in recipe["prep"])))
        n += len(recipe["prep"])
    for i, s in enumerate(logical):
        items = list(s["prep"])
        for r in s["roots"]:
            cook_steps(r, items)
        body.append("<h3>Stage %d · %s%s</h3><ol start='%d'>%s</ol>" % (
            i + 1, esc(s["name"]), " — side stage" if s["side"] else "", n,
            "".join("<li>%s</li>" % esc(x) for x in items)))
        n += len(items)
    body.append("</div>")
    body.append(notes_html(recipe))
    return ("<!DOCTYPE html><html lang='en'><head><meta charset='utf-8'>"
            "<meta name='viewport' content='width=device-width, initial-scale=1'>"
            "<title>%s</title><style>%s</style></head><body><div class='card'>%s</div></body></html>"
            % (esc(recipe["title"]), BASE_CSS + PHONE_CSS, "\n".join(body)))


# ---------------------------------------------------------------- PNG
def render_png(html_path, png_path, phone=True):
    from playwright.sync_api import sync_playwright
    with sync_playwright() as p:
        kw = {}
        for exe in ("/usr/bin/google-chrome", "/usr/bin/chromium", "/usr/bin/chromium-browser"):
            if os.path.exists(exe):
                kw["executable_path"] = exe
                break
        try:
            b = p.chromium.launch(**kw)
        except Exception:
            b = p.chromium.launch()
        if phone:
            pg = b.new_page(viewport={"width": PHONE_W + 2 * PHONE_PAD, "height": 800},
                            device_scale_factor=2, is_mobile=False)
            pg.goto("file://" + os.path.abspath(html_path))
            pg.wait_for_load_state("networkidle")
            over = pg.evaluate("() => document.documentElement.scrollWidth - window.innerWidth")
            if over > 0:
                print("warning: content overflows phone width by %dpx" % over, file=sys.stderr)
            pg.screenshot(path=png_path, full_page=True)
        else:
            pg = b.new_page(viewport={"width": 2400, "height": 300}, device_scale_factor=1)
            pg.goto("file://" + os.path.abspath(html_path))
            pg.wait_for_load_state("networkidle")
            box = pg.evaluate("""() => { const r = document.querySelector('.card').getBoundingClientRect();
                                           return {w: Math.ceil(r.right) + 14, h: Math.ceil(r.bottom) + 16}; }""")
            pg.set_viewport_size({"width": box["w"], "height": box["h"]})
            pg.screenshot(path=png_path, full_page=True)
        b.close()

def main():
    ap = argparse.ArgumentParser(description="Render a Cooking for Engineers recipe card.")
    ap.add_argument("json")
    ap.add_argument("-o", "--out", help="output basename (without extension)")
    ap.add_argument("--wide", action="store_true", help="single wide grid (for printing)")
    ap.add_argument("--max-cols", type=int, default=4,
                    help="phone mode: max step columns per table, also capped by 17px width budget (2 at 430px)")
    ap.add_argument("--width", type=int, default=620, help="wide mode: table width in px")
    ap.add_argument("--no-png", action="store_true")
    a = ap.parse_args()
    recipe = json.load(open(a.json, encoding="utf-8"))
    base = a.out or os.path.splitext(a.json)[0]
    os.makedirs(os.path.dirname(os.path.abspath(base)), exist_ok=True)
    doc = render_wide(recipe, a.width) if a.wide else render_phone(recipe, a.max_cols)
    with open(base + ".html", "w", encoding="utf-8") as f:
        f.write(doc)
    print("wrote", base + ".html")
    if not a.no_png:
        render_png(base + ".html", base + ".png", phone=not a.wide)
        print("wrote", base + ".png")

if __name__ == "__main__":
    main()
